DATA["DT-001"] = ("方向:父病可愈(终局单一:愈)。父母子水为用伏于初爻寅木之下,官鬼申金五爻独发--申金生子水,原神动而生伏用,飞神寅木虽泄伏而申金冲寅开飞,伏神待出有力;病势近段沉重,远段转愈,一段终局之外远段触发为申金动冲飞。应期双层:窗口为本旬内(日档,近病尺度),主坐标子日(伏神逢值填实)。",
 "卦雷水解,春辛未日。用神候选枚举:现卦无父母同亲,变爻无父母,日月未/辛非父母之亲,故取伏神子水(第1源至4源次序照用神章);飞伏核:伏得申金动爻生(有用),飞寅木旺相泄伏为制,四项待出判据满足生扶与冲飞两路。决策序:子水春月休囚但得动爻申金生扶,假伏待出不断死。对象复述:主断语承受对象=占者之父、应验对象=父母爻所指之父,同一。门类应期对表:病占首选逢值/出空类,主坐标取子日与对表同向;D项四路:冲飞申冲寅已现于动爻、填实子日为首选,冲空/解法路无候选已明写。动化方向:申金→子水:生,核对无误;动化定性裁决表留痕:动化方向=原神生用吉向,反转条件=无(三类反转信号未全立)。"+rev("填实子日","冲飞路以申日复推,申日为飞开之期与子日同旬,裁决按门类对表取逢值子日为主坐标、申日舍入reasoning"), (0.55), (False, True, False, "六爻:本卦父母不上卦取伏神子水为主用,reserve_used=true;无变卦名载于卡面且主断未因变卦改判,changed_main=false;排盘动爻与飞伏叙述卡面完整无歧,disputed=false"))
DATA["DT-002"] = ("方向:母子平安(终局单一:安)。妻孕占:妻财酉金为妻用伏于世戌土之下飞来生伏得长生,子孙戌土持世旺相主胎安;三爻兄弟午火动克伏财、六爻父母寅木动,主孕中有惊耗、产期前后有虚惊而终安,不主母子大凶。应期双层:窗口为产期所在旬月内(月档偏日档之间的旬窗,近事尺度取旬窗),主坐标酉日(伏财逢值出伏)。",
 "卦山水蒙,秋壬午日。用神:妻财不上卦现爻,取伏神酉金,飞戌土生伏(飞来生伏得长生,有用项);子孙丑土伏世下另记应验位。兄弟午火动为忌神克财,然午火秋月休囚、伏财得飞生,克力有限。决策序走完:伏财有气待出、不断凶。对象复述:承受对象=占者之妻与胎,妻断落妻财爻、胎断落子孙爻,各归其位同一。应期三路:逢值酉日取中,冲飞卯冲酉为解法候选舍(冲伏反伤),填实无空不取。动化定性:动化方向=忌神动而休囚力量级下调,反转条件=无。卡面载原文动爻以飞伏语叙述、图解本整理为蒙之升,动爻组读法源头有歧,已降置信。"+rev("逢值酉日","出伏路以冲飞卯日复推,卯冲酉兼冲伏神本身,裁决弃冲飞取逢值"), 0.50, (True, True, True, "六爻:图解本整理为蒙之升、主断据动爻组改判,changed_main=true;妻财与子孙俱伏藏取用,reserve_used=true;卡面明载原文飞伏语与图解本整理动爻位置有歧,disputed=true"))
DATA["DT-003"] = ("方向:人平安、迟归(终局单一:归)。子出商未归:子孙申金为用临应,夏癸卯日申金休囚,二爻父母午火旺相独发克申--父母动主音信先至、人受途中阻滞或小病耗,克力虽旺而申金得辰戌土生扶链未绝,断人安无大凶、归期迟。应期双层:窗口为本月内(月档下日窗,行人近事),主坐标申日(用神逢值)。近段无归、远段归,远段触发为用神逢值之申日与其原神土爻填实。",
 "卦艮为山八纯,夏癸卯日。用神子孙申金现卦临应,候选唯一。旺衰:申金夏月休囚,午火父母旺动克之,然世寅木、辰戌土生金之链在。决策序:用神休囚受克但有生扶,降为迟滞中间等级不断死。对象复述:承受对象=出商之子、应验对象=子孙爻所指之子,同一;父母动之音信断落父母爻不回收到本人。应期:逢值申日取中,冲实无空、填实无墓,二路舍弃理由为无空无墓。动化:午火动化何神卡面未载变爻全列,只按动克论、动化方向存疑处已降置信;裁决表留痕:动化方向=忌克用神向,反转条件=无。"+rev("逢值申日","原神填实以辰日复推,辰生申而非归期本体,裁决取逢值"), 0.52, (False, False, False, "六爻:独爻动而卡面未载变卦名、主断未据变卦改判,changed_main=false;用神现卦临应未用伏神,reserve_used=false;排盘完整无歧,disputed=false"))
DATA["DT-004"] = ("方向:子病凶重、难愈(终局单一:不愈倾向)。子病占:子孙丑土为用二爻独发,秋庚寅日丑土休囚,官鬼亥水持世旺相,子孙动而受鬼旺之势压、又寅日木气克土,原神巳火伏无气不能生土,救应薄弱;近段病进,远段无转愈触发可指,明言一段终局、远段无据不报之外的凶势延续。应期双层:窗口为本旬内(日档,近病尺度),主坐标丑日(用神逢值见凶之期,凶应期非愈期)。",
 "卦天火同人,秋庚寅日。用神子孙丑土现卦独发,候选含变爻同亲核:卡面动爻组原文飞伏交错、图解本整理为同人之兑,三处动位并记,读法有歧已降置信并以原文三处并记为准。旺衰:丑土秋月休囚、寅日克泄,官鬼亥水临世得秋金生而旺,子孙动化方向卡面未全列、不臆断进退。决策序第7步:用神休囚无气+原神伏无气+鬼旺克压,凶断条件近全立,故落难愈而仍留倾向二字。对象复述:承受对象=他人之患病子、应验对象=子孙爻,同一。动化定性裁决表:动化方向=存疑(变爻未全列),反转条件=无。"+rev("逢值丑日见凶","冲实路以未日冲丑复推,未冲丑为冲动见事之期同旬同向,裁决取逢值丑日"), 0.55, (True, False, True, "六爻:图解本整理为同人之兑、主断参考变卦,changed_main=true;用神现卦发动未用伏神,reserve_used=false;卡面明载动爻组读法有歧、原文与图解本整理并记,disputed=true"))
DATA["DT-005"] = ("方向:子病可愈(终局单一:愈)。子病占:子孙亥水为用临应,冬甲戌日亥水得月建之气,五爻兄弟酉金独发--酉金为原神生亥水,原神动而生用有力,官鬼午火休囚在冬不能为大害;近段病势在,远段得药转愈,远段触发为酉金动生亥水。应期双层:窗口为本旬内(日档),主坐标亥日(用神逢值)。",
 "卦泽水困,冬甲戌日。用神子孙亥水现卦临应候选唯一;原神兄弟酉金动生用,忌神官鬼午火冬月休囚。决策序:用神有气、原神动生,虽卦名困主近段困滞,不碍终局愈。对象复述:承受对象=患病之子、应验对象=子孙爻,同一。应期三路:逢值亥日取中,填实无空舍,冲实巳冲亥为冲动候选舍(冲用本体作应期次选、已注舍因)。门类应期对表:病占首选逢值,取中。动化方向核:酉金→亥水:生,无误;裁决表:动化方向=原神生用吉向,反转条件=无。"+rev("逢值亥日","冲实巳日复推,巳冲亥动而见愈机,同旬;裁决按对表逢值优先取亥日"), 0.57, (False, False, False, "六爻:独爻动卡面未载变卦名、主断未据变卦改判,changed_main=false;用神现卦未用伏神,reserve_used=false;排盘完整无歧,disputed=false"))
DATA["DT-006"] = ("方向:子病凶、难愈(终局单一:不愈倾向)。父占子病:子孙巳火为用伏于五爻父母子水之下,伏神被飞神子水克压,五爻父母子水又发动克伏,春癸卯日巳火休囚、卯木虽生火而飞压未开,冲飞之路卡面未见;原神受制、药力难达,病凶重。应期双层:窗口为本旬内(日档,近病),主坐标巳日(伏神逢值见凶之期)。一段终局,远段转愈无触发可指、明言远段无据不报其愈。",
 "卦山风蛊,春癸卯日。用神子孙不上卦现爻(巳火仅伏),变爻核:四爻飞伏妻财土动、五爻父母子水动,变爻无子孙同亲,日月卯/癸非子孙之亲,故取伏神巳火。飞伏清单:伏休囚、飞子水旺相克伏(无用项多),待出四项仅得卯木生扶一路,待出不成立。决策序第7步:休囚无气+飞旺克伏无出路,凶断成立。对象复述:承受对象=占者之子、应验对象=伏神子孙所指之子,同一。动化方向:子水→巳火:克,核对无误;裁决表:动化方向=飞神动克伏凶向,反转条件=无(伏神引拨四项未全立)。卡面飞伏语与图解本蛊之鼎整理并存,读法源头有歧已降置信。"+rev("逢值巳日见凶","冲飞路以亥日冲巳复推,亥冲巳兼冲伏本体,裁决弃之取逢值"), 0.60, (True, True, True, "六爻:图解本整理为蛊之鼎、断语参考变卦,changed_main=true;子孙伏藏取用,reserve_used=true;卡面明载原文飞伏语与图解本整理并存,disputed=true"))
DATA["DT-007"] = ("方向:家宅不安、有失财暗耗(终局单一:不利)。家宅占:世爻兄弟午火持世,四爻妻财酉金玄武独发--财动带玄武主暗中失财、盗耗或因财起宅不安,酉金春月休囚财动不久,宅之父母寅木安静、子孙未辰在卦主宅内人口无大灾,凶只落财与宅安一面。应期双层:窗口为本月内(月档下日窗),主坐标酉日(财爻逢值应耗之期)。",
 "卦火水未济,春正月戊戌日。用神家宅综合以世爻与妻财、父母分指:财面落妻财酉金动爻、宅体落父母寅木静爻,对象分指已核同一面各归其爻。酉金正月休囚、戌日土生,动而有气应耗。玄武乘财只作象意辅助不断主线(承装卦六神条)。应期三路:逢值酉日取中,冲实卯冲酉为冲动候选舍因卯木同时生世火吉凶混杂,填实无空舍。动化方向:酉金变爻卡面未载全列,只按财动论,动化方向存疑已注;裁决表:动化方向=财动耗散向,反转条件=无。"+rev("逢值酉日","冲实卯日复推,卯冲酉同指财动之期,裁决按逢值优先取酉日"), 0.55, (False, False, False, "六爻:独爻动卡面未载变卦名、主断未据变卦改判,changed_main=false;用神现卦未用伏神,reserve_used=false;排盘完整无歧,disputed=false"))

