def tradition_of(cid):
    if cid.startswith("BZ-30") and cid in ("BZ-301","BZ-302"): return "bazi"
    if cid in ("BZ-303","BZ-304"): return "fengshui"
    if cid.startswith("BZ-"): return "bazi"
    if cid.startswith("DT-") or cid.startswith("LY-"): return "liuyao"
    return "liuren"

NO_TRAD = {"BZ-032","BZ-035","BZ-036","BZ-037","BZ-038","BZ-041","LR-001","LR2-013","LR2-014","LR2-015","LR2-016","LR2-017","LR2-018","LR2-019","LR2-020","LR2-021","LR2-022","LR2-023","LR2-024","LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107","LR3-110","LR3-112","LR3-114","LR3-116","LY-002","LY-008"}
# LY-001 has system=liuyao not tradition; LY-002/008 no tradition key
NO_TRAD.add("LY-001")

counts={"changed_main":0,"reserve_used":0,"disputed":0}
n=0
for cid,(pred,body,conf,trig) in DATA.items():
    trad=tradition_of(cid)
    if cid in NO_TRAD:
        first=f"tradition={trad}（输入卡无tradition字段，据题面体裁自决）"
    else:
        first=f"tradition={trad}"
    systems = "liuyao纳甲" if trad=="liuyao" else ("子平八字" if trad=="bazi" else ("大六壬" if trad=="liuren" else "三元九运地运/干支年运"))
    basis=f"{first}\nsystems_used=[{systems}]\n{body}"
    if trig is None:
        trigger={"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}
    else:
        cm,ru,di,reason=trig
        trigger={"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":reason}
        counts["changed_main"]+=cm; counts["reserve_used"]+=ru; counts["disputed"]+=di
    rec={"case_id":cid,"prediction_text":pred,"basis":basis,"confidence":conf,"trigger":trigger}
    (OUT/f"{cid}.json").write_text(json.dumps(rec,ensure_ascii=False,indent=1),encoding="utf-8")
    n+=1
print("written",n,"liuyao trigger counts",counts)
